/** Folder names under public/assets/ — each is one collection of Gary's work. */
export type CollectionId = 'intro-images' | 'collage-pieces' | 'finding-reasons' | 'lips';

export interface ImageVariant {
  /** URL relative to the site root, e.g. "images/lips/2-buble-fish-edit-800.webp". */
  src: string;
  width: number;
  height: number;
}

/** Facts about one original file. Generated by scripts/build-images.mjs. */
export interface ArtworkFile {
  /** Stable id: "<collection>/<slug of filename>". Changes only if the file is renamed. */
  id: string;
  collection: CollectionId;
  /** Exact original filename (relative to the collection folder). */
  fileName: string;
  /** URL of the untouched original, path segments encoded once. Not deployed by default (see README). */
  originalSrc: string;
  width: number;
  height: number;
  /** Numeric filename prefix ("1a.Splash dragon" -> 1), or null when the filename has none. */
  sequence: number | null;
  sequenceLabel: string | null;
  /** Optimized display copies, ascending by width. */
  variants: ImageVariant[];
  /** Largest optimized copy, used for zoomed viewing. */
  detail: ImageVariant;
}

/**
 * single    — one photograph; may be deliberately cropped for promotional thumbnails.
 * composite — diptych, triptych, collage, bordered or embedded-text piece; always shown whole.
 */
export type ArtworkFormat = 'single' | 'composite';

/** Hand-curated information about an artwork. Lives in artwork-details.ts. */
export interface ArtworkDetails {
  /** Describes what is visible. No invented symbolism. */
  alt: string;
  format: ArtworkFormat;
  /** Only titles Gary has confirmed. Filename-derived working titles stay in `notes`. */
  title?: string;
  /** Id of a SourceText paired with this image (see site-text.ts). */
  textId?: string;
  /** Verified transcript of text embedded in the artwork itself. Never guessed. */
  transcript?: string;
  /** CSS object-position used when a crop is allowed (format 'single'). */
  focal?: string;
  /** Overrides filename/sequence order within the collection. Lower comes first. */
  order?: number;
  /** Internal notes for review. Never rendered. */
  notes?: string;
}

/** A passage of Gary's own words, stored verbatim. */
export interface SourceText {
  id: string;
  collection: CollectionId;
  /** Number as supplied by the client (statements and poems are numbered per collection). */
  number?: number;
  kind: 'statement' | 'poem' | 'definition';
  /** Verbatim text with original punctuation and line breaks. null = copy still pending. */
  text: string | null;
  /** Internal notes for review. Never rendered. */
  notes?: string;
}

export interface Artwork extends ArtworkFile, ArtworkDetails {
  /** width / height */
  ratio: number;
  /** Paired text, only when it exists and is not pending. */
  text: SourceText | null;
}

export interface CollectionInfo {
  id: CollectionId;
  /** Public label for the collection. */
  label: string;
  /** Route of the page the collection appears on. */
  route: string;
  /** In-page anchor for the collection section. */
  anchor: string;
}
